<?php declare(strict_types=1); namespace App\Domains\WorkCore\System\Contracts\Records\Adapters; use App\Domains\WorkCore\System\Contracts\Records\ReviewAccessContract; use Illuminate\Database\ConnectionInterface; final class ReviewAccessAdapter implements ReviewAccessContract { public function __construct(private ConnectionInterface $db){} public function find(int $companyId,string $publicId): ?array{$r=$this->db->table('tz_reviews')->where('company_id',$companyId)->where('public_id',$publicId)->whereNull('deleted_at')->first();return $r?(array)$r:null;} }
